import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export function initStepsAnimation(container: HTMLElement): () => void {
  const ctx = gsap.context(() => {
    // Kill any horizontal overflow generated by GSAP pinning
    container.style.overflowX = "hidden";

    const cards = container.querySelectorAll<HTMLElement>('[data-step-card]');
    if (cards.length === 0) return;

    cards.forEach((card) => {
      // Direct guard against horizontal bleed on individual cards
      card.style.overflow = "hidden";

      const num = card.querySelector('[data-animate-num]');
      const title = card.querySelector('[data-animate-title]');
      const bgNum = card.querySelector<HTMLElement>('[data-animate-bg]');
      const desc = card.querySelector('[data-animate-desc]');
      const deliverables = card.querySelectorAll('[data-animate-item]');

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: card,
          start: "top top",
          end: "+=130%",
          pin: true,
          scrub: 0.8,
          anticipatePin: 1,
        },
      });

      // Pure vertical setup to guarantee NO X-axis width expansion
      if (bgNum) {
        gsap.set(bgNum, {
          scale: 1.25,
          opacity: 0,
          clipPath: "inset(15% 15% 15% 15%)",
          backgroundPosition: "0% 50%",
          filter: "brightness(0.6) contrast(1.2)",
        });
      }

      // ASSEMBLY (Using Y movements only)
      tl.fromTo(num, { y: -50, opacity: 0 }, { y: 0, opacity: 1, duration: 0.8, ease: "power3.out" })
        .fromTo(
          title,
          { y: 40, opacity: 0 },
          { y: 0, opacity: 1, duration: 1, ease: "power3.out" },
          "-=0.6"
        );

      // CRAZY MASKED NUMBER ENTRANCE
      if (bgNum) {
        tl.to(
          bgNum,
          {
            scale: 1,
            opacity: 1,
            clipPath: "inset(0% 0% 0% 0%)",
            filter: "brightness(1) contrast(1)",
            duration: 1.4,
            ease: "expo.out",
          },
          "-=0.8"
        );
      }

      tl.fromTo(desc, { y: 50, opacity: 0 }, { y: 0, opacity: 1, duration: 0.8, ease: "power2.out" }, "-=1")
        .fromTo(
          deliverables,
          { y: 30, opacity: 0 },
          { y: 0, opacity: 1, stagger: 0.12, duration: 0.6, ease: "power2.out" },
          "-=0.6"
        );

      // READING HOLD WINDOW + INSIDE-TEXT PARALLAX DRIFT
      if (bgNum) {
        tl.to(
          bgNum,
          {
            backgroundPosition: "100% 50%",
            duration: 2,
            ease: "none",
          },
          "-=0.2"
        );
      } else {
        tl.to({}, { duration: 2 });
      }

      // DECONSTRUCTION (Imploding mask exit)
      tl.to(num, { y: -40, opacity: 0, duration: 0.5, ease: "power2.in" })
        .to(title, { y: -30, opacity: 0, duration: 0.5, ease: "power2.in" }, "<");

      if (bgNum) {
        tl.to(
          bgNum,
          {
            scale: 0.8,
            opacity: 0,
            clipPath: "inset(20% 10% 20% 10%)",
            filter: "brightness(0.4)",
            duration: 0.7,
            ease: "power2.inOut",
          },
          "<"
        );
      }

      tl.to(desc, { y: -30, opacity: 0, duration: 0.5, ease: "power2.in" }, "<").to(
        deliverables,
        { opacity: 0, y: -20, duration: 0.4, ease: "power2.in" },
        "<"
      );
    });
  }, container);

  return () => ctx.revert();
}